from __future__ import annotations

from collections import Counter
import math

from .model import Case, Plan, Query, Rows, validate_case

_BINARY = {
    "add": "+", "sub": "-",
    "eq": "=", "ne": "<>", "lt": "<", "le": "<=", "gt": ">", "ge": ">=",
    "and": "AND", "or": "OR",
}
_SOURCES = {
    "single": "t",
    "inner": "t INNER JOIN u ON t.k = u.k",
    "left": "t LEFT JOIN u ON t.k = u.k",
}
_AGGREGATES = ("count", "sum", "avg", "min", "max")


def expr_sql(expr: list, params: list) -> str:
    """Render a validated expression, appending literal values to params."""
    op = expr[0]
    if op == "col":
        return f"{expr[1]}.{expr[2]}"
    if op == "lit":
        params.append(expr[1])
        return "?"
    if op == "not":
        return f"(NOT {expr_sql(expr[1], params)})"
    if op == "isnull":
        return f"({expr_sql(expr[1], params)} IS NULL)"
    if op in _BINARY:
        left = expr_sql(expr[1], params)
        right = expr_sql(expr[2], params)
        return f"({left} {_BINARY[op]} {right})"
    raise ValueError(f"unsupported expression operator {op!r}")


def source_sql(source: str) -> str:
    if source not in _SOURCES:
        raise ValueError(f"invalid source {source!r}")
    return _SOURCES[source]


def _render_list(exprs: list, params: list) -> list[str]:
    return [expr_sql(e, params) for e in exprs]


def _query(case: Case, select_kind: str, condition: str | None) -> Query:
    """Build one SELECT.

    select_kind: "base" for the baseline projection/aggregate, "part" for the
    partition layout.  condition selects the partition: None, "true",
    "false" or "unknown".
    """
    mode = case["mode"]
    params: list = []
    distinct = ""
    if mode in ("rows", "distinct"):
        items = _render_list(case["select"], params)
        if mode == "distinct":
            distinct = "DISTINCT "
    else:
        items = _render_list(case["group_by"], params)
        value = case["value"]
        value_sql = None if value is None else expr_sql(value, params)
        if mode == "count":
            items.append("COUNT(*)" if value_sql is None else f"COUNT({value_sql})")
        elif mode in ("sum", "avg") and select_kind == "part":
            # Sufficient statistics; the value is rendered twice, so its
            # parameters must be appended twice in textual order.
            second = expr_sql(value, params)
            items.append(f"SUM({value_sql})")
            items.append(f"COUNT({second})")
        else:
            items.append(f"{mode.upper()}({value_sql})")
    sql = f"SELECT {distinct}{', '.join(items)} FROM {source_sql(case['source'])}"

    clauses = []
    if case["where"] is not None:
        clauses.append(f"({expr_sql(case['where'], params)})")
    if condition is not None:
        predicate = expr_sql(case["predicate"], params)
        if condition == "true":
            clauses.append(f"({predicate})")
        elif condition == "false":
            clauses.append(f"(NOT ({predicate}))")
        elif condition == "unknown":
            clauses.append(f"(({predicate}) IS NULL)")
        else:  # pragma: no cover - internal misuse
            raise ValueError(condition)
    if clauses:
        sql += " WHERE " + " AND ".join(clauses)
    if mode in _AGGREGATES and case["group_by"]:
        sql += " GROUP BY " + ", ".join(_render_list(case["group_by"], params))
    return Query(sql, tuple(params))


def compile_case(case: Case) -> Plan:
    validate_case(case)
    base = _query(case, "base", None)
    parts = tuple(_query(case, "part", c) for c in ("true", "false", "unknown"))
    group_count = len(case["group_by"]) if case["mode"] in _AGGREGATES else 0
    return Plan(base=base, parts=parts, mode=case["mode"], group_count=group_count)


def _cell_key(value: object) -> tuple:
    """Type-sensitive hashable key: 1, 1.0, "1" and NULL are all distinct."""
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("int", value)
    if isinstance(value, float):
        if math.isnan(value):
            return ("float", "nan")
        return ("float", value)
    if isinstance(value, str):
        return ("text", value)
    if isinstance(value, (bytes, bytearray, memoryview)):
        return ("blob", bytes(value))
    return ("other", type(value).__name__, repr(value))


def _row_key(row) -> tuple:
    return tuple(_cell_key(c) for c in row)


def _sort_class(value: object) -> int:
    # SQLite storage-class ordering: NULL < numeric < text < blob.
    if value is None:
        return 0
    if isinstance(value, (int, float)):
        return 1
    if isinstance(value, str):
        return 2
    return 3


def _less(a: object, b: object) -> bool:
    ca, cb = _sort_class(a), _sort_class(b)
    if ca != cb:
        return ca < cb
    return a < b  # type: ignore[operator]


def _as_rows(rows) -> Rows:
    if rows is None or isinstance(rows, (str, bytes, dict)):
        raise ValueError("partition result must be a list of rows")
    out = []
    for row in rows:
        if row is None or isinstance(row, (str, bytes, dict)):
            raise ValueError("partition row must be a sequence of cells")
        out.append(list(row))
    return out


def compose(plan: Plan, partition_rows: list[Rows]) -> Rows:
    if partition_rows is None or len(partition_rows) != 3:
        raise ValueError("exactly three partition results are required")
    parts = [_as_rows(rows) for rows in partition_rows]
    mode = plan.mode

    if mode == "rows":
        return [list(row) for rows in parts for row in rows]
    if mode == "distinct":
        seen: set = set()
        result = []
        for rows in parts:
            for row in rows:
                key = _row_key(row)
                if key not in seen:
                    seen.add(key)
                    result.append(list(row))
        return result
    if mode not in _AGGREGATES:
        raise ValueError(f"invalid plan mode {mode!r}")

    g = plan.group_count
    width = g + (2 if mode in ("sum", "avg") else 1)
    states: dict = {}
    order: list = []

    def state_for(group: list):
        key = _row_key(group)
        if key not in states:
            states[key] = [list(group), None, 0]  # group, value/total, count
            order.append(key)
        return states[key]

    if g == 0:
        state_for([])  # ungrouped aggregates always yield one row
    for rows in parts:
        for row in rows:
            if len(row) != width:
                raise ValueError(
                    f"{mode} partition row has {len(row)} columns, expected {width}")
            st = state_for(row[:g])
            if mode == "count":
                st[1] = row[g] if st[1] is None else st[1] + row[g]
            elif mode in ("sum", "avg"):
                partial, n = row[g], row[g + 1]
                if partial is not None:
                    st[1] = partial if st[1] is None else st[1] + partial
                st[2] = st[2] + n
            else:
                value = row[g]
                if value is not None:
                    if st[1] is None:
                        st[1] = value
                    elif mode == "min" and _less(value, st[1]):
                        st[1] = value
                    elif mode == "max" and _less(st[1], value):
                        st[1] = value

    result = []
    for key in order:
        group, value, count = states[key]
        if mode == "count":
            out = 0 if value is None else value
        elif mode == "sum":
            out = None if count == 0 or value is None else value
        elif mode == "avg":
            out = None if count == 0 or value is None else value / count
        else:
            out = value
        result.append(group + [out])
    return result


def equivalent(expected: Rows, actual: Rows) -> bool:
    return Counter(_row_key(r) for r in expected) == Counter(_row_key(r) for r in actual)
