def _rows(result) -> list:
    if result is None or isinstance(result, (str, bytes, dict)):
        raise TypeError("executor must return a list of rows")
    rows = []
    for row in result:
        if row is None or isinstance(row, (str, bytes, dict)):
            raise TypeError("executor rows must be sequences of cells")
        rows.append(list(row))
    return rows


def run_case(case: Case, executor: Executor | None = None) -> dict:
    plan = compiler.compile_case(case)  # validates before any SQL runs
    run = executor if executor is not None else storage.execute
    connection = storage.open_database(case)
    try:
        expected = _rows(run(connection, plan.base))
        parts = [_rows(run(connection, query)) for query in plan.parts]
    finally:
        connection.close()
    actual = compiler.compose(plan, parts)
    return {"ok": bool(compiler.equivalent(expected, actual)),
            "expected": expected, "actual": actual}


def _check_result_shape(result: object) -> None:
    if not isinstance(result, dict):
        raise ValueError("result must be an object")
    for key in ("ok", "expected", "actual"):
        if key not in result:
            raise ValueError(f"result is missing {key!r}")
    if not isinstance(result["ok"], bool):
        raise ValueError("result.ok must be a boolean")
    for key in ("expected", "actual"):
        rows = result[key]
        if not isinstance(rows, list) or not all(isinstance(r, list) for r in rows):
            raise ValueError(f"result.{key} must be a list of rows")


def _dumps(data: object) -> str:
    # ASCII-escaped JSON is valid UTF-8, survives lone surrogates and line
    # separator characters, and round-trips exactly.
    return json.dumps(data, ensure_ascii=True, allow_nan=False, indent=2) + "\n"


def write_text_atomic(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(text)
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass
        raise


def save_failure(path: str | Path, case: Case, result: dict) -> None:
    validate_case(case)
    _check_result_shape(result)
    if result["ok"]:
        raise ValueError("refusing to save a passing result as a failure")
    artifact = {"version": 1, "case": case, "result": result}
    write_text_atomic(Path(path), _dumps(artifact))


def _reject_constant(name: str):
    raise ValueError(f"invalid JSON constant {name}")


def load_artifact(path: str | Path) -> dict:
    path = Path(path)
    if not path.is_file():
        raise FileNotFoundError(f"artifact not found: {path}")
    try:
        text = path.read_text(encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError(f"artifact is not UTF-8: {path}") from exc
    try:
        artifact = json.loads(text, parse_constant=_reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError(f"artifact is not valid JSON: {exc}") from exc
    if not isinstance(artifact, dict) or set(artifact) != {"version", "case", "result"}:
        raise ValueError("artifact must have exactly version, case and result")
    if type(artifact["version"]) is not int or artifact["version"] != 1:
        raise ValueError("unsupported artifact version")
    validate_case(artifact["case"])
    _check_result_shape(artifact["result"])
    return artifact


def replay(path: str | Path, executor: Executor | None = None) -> dict:
    artifact = load_artifact(path)
    # The recorded result is deliberately ignored: rebuild and rerun.
    return run_case(artifact["case"], executor)
