from __future__ import annotations

import hashlib
import random

from . import compiler, storage
from .model import MODES, SOURCES, Case, validate_case

MAX_COUNT = 4096
BLOCK = 112
_MAX_TRIES = 250
_INT_MIN, _INT_MAX = -(2 ** 63), 2 ** 63 - 1

_CMP = ("eq", "ne", "lt", "le", "gt", "ge")
_AGG = ("count", "sum", "avg", "min", "max")
# Required operators appear twice per 16-slot cycle; the rest once.
_FOCUS = ("eq", "lt", "and", "or", "not", "isnull",
          "eq", "lt", "and", "or", "not", "isnull",
          "ne", "le", "gt", "ge")
_NUMS = (-1000, -999, -100, -10, -3, -2, -1, 0, 1, 2, 3, 5, 7, 10, 42, 100, 999, 1000)
_TAGS = ("", "a", "A", "b", "a ", " a", "ab", "abc", "Ab", "x'y", "''", '"q"',
         "NULL", "null", "0", "1", "10", "-1", "1.0", "1e3", "%", "_", "a%",
         "\\", "\x00", "a\x00b", "\u00e9", "e\u0301", "\u00df", "SS",
         "\u65e5\u672c", "\U0001F642", "\t", "\n", " ", "zz", "Z", "a" * 32,
         "~", "Robert'); --")


def _rng(*parts: object) -> random.Random:
    material = ":".join(str(p) for p in ("tlp-v1",) + parts).encode()
    return random.Random(int.from_bytes(hashlib.sha256(material).digest(), "big"))


# ---------------------------------------------------------------- slot plan

def _block_slots(seed: int, block: int) -> list[dict]:
    rng = _rng(seed, "block", block)
    slots = []
    for mi, mode in enumerate(MODES):
        js = list(range(16))
        if mode in ("rows", "distinct"):
            targets = ["dups"] * 5 + ["three"] * 6 + ["empty"] + ["nonempty"] * 4
            rng.shuffle(targets)
            tmap = dict(zip(js, targets))
        elif mode == "count":
            star = [j for j in js if (j >> 2) & 1]
            valued = [j for j in js if not (j >> 2) & 1]
            t_star = ["three"] * 3 + ["empty"] + ["nonempty"] * 4
            t_val = ["three"] * 3 + ["allnull"] * 2 + ["empty"] + ["nonempty"] * 2
            rng.shuffle(t_star)
            rng.shuffle(t_val)
            tmap = dict(zip(star, t_star))
            tmap.update(zip(valued, t_val))
        else:
            targets = ["three"] * 6 + ["allnull"] * 2 + ["empty"] + ["nonempty"] * 7
            rng.shuffle(targets)
            tmap = dict(zip(js, targets))
        for j in js:
            slots.append({
                "mode": mode,
                "source": SOURCES[(j + mi) % 3],
                "where": bool(j & 1),
                "grouped": mode in _AGG and bool((j >> 1) & 1),
                "count_star": mode == "count" and bool((j >> 2) & 1),
                "focus": _FOCUS[(j + 3 * mi) % 16],
                "target": tmap[j],
            })
    rng.shuffle(slots)
    return slots


# ------------------------------------------------------------ data creation

def _clamp(n: int) -> int:
    return max(-1000, min(1000, n))


def _table(rng: random.Random, n: int, kdom: list, vpool: list, tags: list,
           null_p: float) -> list:
    rows = []
    for i in range(n):
        ident = i + 1 if rng.random() < 0.8 else rng.randint(1, max(1, n))
        if rng.random() < 0.04:
            ident = None
        k = None if rng.random() < null_p else rng.choice(kdom)
        v = None if rng.random() < null_p + 0.05 else rng.choice(vpool)
        tag = None if rng.random() < null_p else rng.choice(tags)
        rows.append([ident, k, v, tag])
    while rows and len(rows) < 32 and rng.random() < 0.3:
        rows.append(list(rng.choice(rows)))
    rng.shuffle(rows)
    return rows


def _tables(rng: random.Random, small: bool = False) -> dict:
    base = rng.randint(-4, 3)
    kdom = list(range(base, base + rng.randint(2, 5)))
    if rng.random() < 0.15:
        kdom.append(rng.choice(_NUMS))
    vpool = rng.sample(_NUMS, rng.randint(1, 3)) + [
        rng.randint(-50, 50) for _ in range(rng.randint(1, 4))]
    tags = rng.sample(_TAGS, rng.randint(2, 5))
    if small or rng.random() < 0.7:
        nt, nu = rng.randint(3, 12), rng.randint(2, 8)
    else:
        nt, nu = rng.randint(10, 32), rng.randint(5, 32)
    ukdom = kdom[:]
    if rng.random() < 0.5:
        ukdom = ukdom[1:] + [kdom[-1] + 1]
    null_p = rng.choice((0.0, 0.1, 0.2, 0.3))
    t = _table(rng, nt, kdom, vpool, tags, null_p)
    u = _table(rng, nu, ukdom, vpool + [rng.randint(-20, 20)], tags, rng.choice((0.0, 0.15, 0.3)))
    return {"t": t, "u": u}


# ------------------------------------------------------- expression creation

_COLIDX = {"id": 0, "k": 1, "v": 2, "tag": 3}


class _Gen:
    def __init__(self, rng: random.Random, source: str, tables: dict):
        self.rng = rng
        self.source = source
        self.tables = tables
        tabs = ("t",) if source == "single" else ("t", "u")
        self.num_cols = [(tb, c) for tb in tabs for c in ("id", "k", "v")]
        self.text_cols = [(tb, "tag") for tb in tabs]

    def values(self, tb: str, col: str) -> list:
        idx = _COLIDX[col]
        return [r[idx] for r in self.tables[tb] if r[idx] is not None]

    def col(self, numeric: bool | None = None) -> list:
        if numeric is None:
            numeric = self.rng.random() < 0.7
        if numeric:
            weights = [1 if c == "id" else 3 for _, c in self.num_cols]
            tb, c = self.rng.choices(self.num_cols, weights)[0]
        else:
            tb, c = self.rng.choice(self.text_cols)
        return ["col", tb, c]

    def num_lit(self, base: list | None = None, offset: int = 0) -> list:
        rng = self.rng
        vals = self.values(base[1], base[2]) if base else []
        r = rng.random()
        if vals and r < 0.6:
            return ["lit", _clamp(rng.choice(vals) + offset)]
        if vals and r < 0.8:
            return ["lit", _clamp(rng.choice(vals) + offset + rng.choice((-1, 1)))]
        if r < 0.97:
            return ["lit", rng.choice(_NUMS) if rng.random() < 0.4 else rng.randint(-20, 20)]
        return ["lit", None]

    def text_lit(self, base: list | None = None) -> list:
        rng = self.rng
        vals = self.values(base[1], base[2]) if base else []
        r = rng.random()
        if vals and r < 0.65:
            return ["lit", rng.choice(vals)]
        if vals and r < 0.75:
            return ["lit", rng.choice(vals)[:1]]
        if r < 0.97:
            return ["lit", rng.choice(_TAGS)]
        return ["lit", None]

    def numeric(self, budget: int) -> list:
        """Numeric scalar with depth <= budget."""
        rng = self.rng
        r = rng.random()
        if budget >= 2 and r < 0.25:
            op = rng.choice(("add", "sub"))
            left = self.col(True)
            right = self.numeric(budget - 1) if rng.random() < 0.4 else (
                ["lit", rng.randint(-5, 5)] if rng.random() < 0.6 else self.col(True))
            return [op, left, right] if rng.random() < 0.8 else [op, right, left]
        if r < 0.9:
            return self.col(True)
        return ["lit", rng.randint(-10, 10)]

    def scalar(self, budget: int) -> list:
        rng = self.rng
        r = rng.random()
        if r < 0.3:
            return self.col(False)
        if r < 0.35:
            return ["lit", rng.choice(_TAGS)]
        return self.numeric(budget)

    def comparison(self, budget: int, op: str | None = None) -> list:
        rng = self.rng
        op = op or rng.choice(_CMP)
        r = rng.random()
        if r < 0.25:  # text comparison
            left = self.col(False)
            if rng.random() < 0.2 and self.source != "single":
                right = ["col", "u" if left[1] == "t" else "t", "tag"]
            elif rng.random() < 0.08:
                right = ["lit", rng.choice((0, 1, 10))]  # affinity conversion
            else:
                right = self.text_lit(left)
        elif r < 0.45 and budget >= 3:  # arithmetic comparison
            base = self.col(True)
            if rng.random() < 0.5:
                delta = rng.randint(-5, 5)
                aop = rng.choice(("add", "sub"))
                left = [aop, base, ["lit", delta]]
                right = self.num_lit(base, delta if aop == "add" else -delta)
            else:
                other = self.col(True)
                left = [rng.choice(("add", "sub")), base, other]
                right = self.num_lit(base)
        else:
            left = self.col(True)
            x = rng.random()
            if x < 0.2:
                right = self.col(True)
            elif x < 0.25:
                right = ["lit", str(rng.choice(self.values(left[1], left[2]) or [0]))]
            else:
                right = self.num_lit(left)
        if rng.random() < 0.15:
            left, right = right, left
        return [op, left, right]

    def predicate(self, budget: int, focus: str | None = None) -> list:
        rng = self.rng
        if focus is None:
            r = rng.random()
            if budget < 3 or r < 0.5:
                focus = rng.choice(_CMP) if rng.random() < 0.85 else "isnull"
            else:
                focus = rng.choice(("and", "and", "or", "or", "not", "isnull"))
        if focus in _CMP:
            return self.comparison(budget, focus)
        if focus in ("and", "or"):
            return [focus, self.predicate(budget - 1), self.predicate(budget - 1)]
        if focus == "not":
            return ["not", self.predicate(budget - 1)]
        if focus == "isnull":
            if budget >= 3 and rng.random() < 0.3:
                return ["isnull", self.predicate(budget - 1)]
            return ["isnull", self.scalar(budget - 1)]
        raise AssertionError(focus)


def _depth(expr: object) -> int:
    if not isinstance(expr, list) or expr[0] in ("col", "lit"):
        return 1
    return 1 + max(_depth(e) for e in expr[1:])


def _columns(expr: list) -> list:
    if expr[0] == "col":
        return [(expr[1], expr[2])]
    if expr[0] == "lit":
        return []
    return [c for e in expr[1:] for c in _columns(e)]


# ---------------------------------------------------------------- measuring

def _measure(case: Case) -> dict:
    params: list = []
    items = [compiler.expr_sql(case["predicate"], params)]
    value = case["value"]
    items.append("NULL" if value is None else compiler.expr_sql(value, params))
    items += [compiler.expr_sql(e, params) for e in case["select"]]
    sql = f"SELECT {', '.join(items)} FROM {compiler.source_sql(case['source'])}"
    if case["where"] is not None:
        sql += f" WHERE {compiler.expr_sql(case['where'], params)}"
    connection = storage.open_database(case)
    try:
        rows = connection.execute(sql, params).fetchall()
    finally:
        connection.close()
    projected = [tuple((type(c).__name__, c) for c in r[2:]) for r in rows]
    return {
        "n": len(rows),
        "true": sum(1 for r in rows if r[0] is not None and r[0]),
        "false": sum(1 for r in rows if r[0] is not None and not r[0]),
        "unknown": sum(1 for r in rows if r[0] is None),
        "allnull": value is not None and bool(rows) and all(r[1] is None for r in rows),
        "dups": len(set(projected)) < len(projected),
    }


def _meets(target: str, m: dict, strict: bool) -> bool:
    if target == "empty":
        return m["n"] == 0
    if m["n"] == 0:
        return False
    if target == "three":
        return m["true"] > 0 and m["false"] > 0 and m["unknown"] > 0
    if target == "allnull":
        return m["allnull"]
    if target == "dups":
        return m["dups"]
    if strict:  # prefer non-degenerate partitioning for ordinary cases
        return sum(1 for k in ("true", "false", "unknown") if m[k]) >= 2
    return True


# ------------------------------------------------------------ case creation

def _empty_where(g: _Gen, rng: random.Random) -> list:
    tb = "t" if g.source == "single" or rng.random() < 0.6 else "u"
    choice = rng.randrange(4)
    if choice == 0:
        col = ["col", tb, rng.choice(("id", "k", "v"))]
        vals = g.values(tb, col[2])
        bound = max(vals) if vals else 0
        return ["gt", col, ["lit", _clamp(bound + rng.randint(0, 3))]] \
            if bound < 1000 else ["lt", col, ["lit", -1000]]
    if choice == 1:
        col = ["col", tb, "tag"]
        present = set(g.values(tb, "tag"))
        absent = [s for s in _TAGS if s not in present] or ["\u2603"]
        return ["eq", col, ["lit", rng.choice(absent)]]
    if choice == 2:
        col = ["col", tb, rng.choice(("k", "v"))]
        return ["and", ["isnull", col], ["ge", col, g.num_lit(col)]]
    col = ["col", tb, rng.choice(("k", "v", "id"))]
    a = rng.randint(-5, 5)
    return ["and", ["eq", col, ["lit", a]], g.predicate(3, rng.choice(("ne", "eq", "or")))
            if rng.random() < 0.3 else ["eq", col, ["lit", a + rng.randint(1, 3)]]]


def _attempt(rng: random.Random, slot: dict) -> Case:
    mode, source, target = slot["mode"], slot["source"], slot["target"]
    tables = _tables(rng)
    if target == "empty" and not slot["where"]:
        if source == "inner" and rng.random() < 0.5:
            if rng.random() < 0.5:
                tables["u"] = []
            else:
                tks = {r[1] for r in tables["t"]}
                for r in tables["u"]:
                    if r[1] in tks:
                        r[1] = 500 + rng.randint(0, 400)
        else:
            tables["t"] = []
    if target == "dups":
        for tb in ("t", "u"):
            rows = tables[tb]
            while rows and len(rows) < 32 and rng.random() < 0.5:
                rows.append(list(rng.choice(rows)))
    g = _Gen(rng, source, tables)

    focus = slot["focus"]
    budget = rng.choice((2, 3, 3, 4, 4, 5, 6)) if focus in _CMP else rng.choice((3, 4, 4, 5, 6))
    if target == "three" and focus == "isnull":
        inner = g.predicate(budget - 1 if budget > 3 else 3, "isnull")
        predicate = [rng.choice(("and", "or")), inner, g.comparison(3)]
        if rng.random() < 0.5:
            predicate[1], predicate[2] = predicate[2], predicate[1]
    else:
        predicate = g.predicate(budget, focus)
        if _depth(predicate) <= 4 and rng.random() < 0.2:
            predicate = [rng.choice(("and", "or")), predicate, g.predicate(2)]

    where = None
    if slot["where"]:
        if target == "empty":
            where = _empty_where(g, rng)
        else:
            where = g.predicate(rng.choice((2, 2, 3, 4)))

    select, value, group_by = [], None, []
    if mode in ("rows", "distinct"):
        n = rng.choice((1, 1, 2, 2, 3))
        for _ in range(n):
            if target == "dups" or rng.random() < 0.3:
                r = rng.random()
                if r < 0.45:
                    select.append(["col", "t", rng.choice(("k", "tag"))])
                elif r < 0.6 and source != "single":
                    select.append(["col", "u", rng.choice(("k", "tag", "v"))])
                elif r < 0.75:
                    select.append(["lit", rng.choice((1, "x", None, 0))])
                else:
                    select.append(g.scalar(2))
            else:
                select.append(g.scalar(rng.choice((1, 2, 3))))
    else:
        if not slot["count_star"]:
            value = g.numeric(rng.choice((1, 1, 2, 3)))
            if rng.random() < 0.05:
                value = ["lit", rng.randint(-5, 5)]
        if slot["grouped"]:
            for _ in range(rng.choice((1, 1, 2))):
                r = rng.random()
                if r < 0.75:
                    group_by.append(g.col(rng.random() < 0.6))
                elif r < 0.95:
                    group_by.append(g.numeric(2))
                else:
                    group_by.append(["lit", rng.choice((1, "g", None))])
        if target == "allnull":
            refs = _columns(value)
            if refs and rng.random() < 0.75:
                choices = [c for c in refs if c[1] != "k" or source == "single"] or refs
                tb, col = rng.choice(choices)
                idx = _COLIDX[col]
                for row in tables[tb]:
                    row[idx] = None
            else:
                value = [rng.choice(("add", "sub")), value, ["lit", None]]
                if rng.random() < 0.5:
                    value = [value[0], value[2], value[1]]
    return {
        "version": 1, "tables": tables, "source": source, "predicate": predicate,
        "where": where, "mode": mode, "select": select, "value": value,
        "group_by": group_by,
    }


def _fallback(slot: dict) -> Case:
    mode, target = slot["mode"], slot["target"]
    t = [[1, 1, 1, "a"], [2, 1, 1, "a"], [3, 2, 5, "b"], [4, None, None, None],
         [5, 2, None, "b"]]
    u = [[1, 1, 10, "x"], [2, 2, 20, "y"], [3, None, None, None]]
    where = None
    if slot["where"]:
        where = ["ge", ["col", "t", "id"], ["lit", 100 if target == "empty" else 1]]
    elif target == "empty":
        t = []
    value = None
    if mode in _AGG and not slot["count_star"]:
        value = ["col", "t", "v"]
        if target == "allnull":
            value = ["add", value, ["lit", None]]
    return {
        "version": 1, "tables": {"t": t, "u": u}, "source": slot["source"],
        "predicate": ["lt", ["col", "t", "v"], ["lit", 3]], "where": where,
        "mode": mode,
        "select": [["col", "t", "tag"]] if mode in ("rows", "distinct") else [],
        "value": value,
        "group_by": [["col", "t", "k"]] if slot["grouped"] else [],
    }


def _make_case(seed: int, index: int, slot: dict) -> Case:
    rng = _rng(seed, "case", index)
    for attempt in range(_MAX_TRIES):
        case = _attempt(rng, slot)
        try:
            validate_case(case)
        except ValueError:
            continue
        if _meets(slot["target"], _measure(case), strict=attempt < 40):
            return case
    case = _fallback(slot)
    validate_case(case)
    return case


def generate(seed: int, count: int) -> list[Case]:
    if type(seed) is not int or not _INT_MIN <= seed <= _INT_MAX:
        raise ValueError("seed must be a signed 64-bit integer")
    if type(count) is not int or not 0 <= count <= MAX_COUNT:
        raise ValueError(f"count must be an integer in [0, {MAX_COUNT}]")
    cases: list[Case] = []
    block = -1
    slots: list[dict] = []
    for index in range(count):
        if index // BLOCK != block:
            block = index // BLOCK
            slots = _block_slots(seed, block)
        cases.append(_make_case(seed, index, slots[index % BLOCK]))
    return cases

