from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import shutil
import sys
import tempfile

from . import generator, runner


def _error(message: str) -> int:
    print(f"tlp: error: {message}", file=sys.stderr)
    return 2


def _dump(data: object, indent: int | None = 2) -> str:
    return json.dumps(data, ensure_ascii=True, allow_nan=False, indent=indent)


def _campaign(seed: int, count: int, out: Path) -> int:
    try:
        cases = generator.generate(seed, count)
    except ValueError as exc:
        return _error(f"invalid campaign arguments: {exc}")

    if out.exists() or out.is_symlink():
        if not out.is_dir():
            return _error(f"output path exists and is not a directory: {out}")
        if any(out.iterdir()):
            return _error(f"refusing to write into nonempty output directory: {out}")

    results = []
    for index, case in enumerate(cases):
        try:
            results.append(runner.run_case(case))
        except Exception as exc:  # execution failure: no success artifacts
            return _error(f"case {index} failed to execute: {type(exc).__name__}: {exc}")

    parent = out.absolute().parent
    try:
        parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix=f".{out.name}.staging-", dir=parent))
    except OSError as exc:
        return _error(f"cannot create output directory: {exc}")
    try:
        mismatches = 0
        for index, (case, result) in enumerate(zip(cases, results)):
            if not result["ok"]:
                mismatches += 1
                runner.save_failure(staging / f"failure-{index:06d}.json", case, result)
        with open(staging / "cases.jsonl", "w", encoding="utf-8") as handle:
            for case in cases:
                handle.write(_dump(case, None) + "\n")
        summary = {"version": 1, "seed": seed, "requested": count,
                   "executed": len(results), "passed": len(results) - mismatches,
                   "mismatches": mismatches}
        with open(staging / "summary.json", "w", encoding="utf-8") as handle:
            handle.write(_dump(summary) + "\n")
        if out.is_dir():
            if any(out.iterdir()):
                raise OSError(f"output directory became nonempty: {out}")
            out.rmdir()
        os.rename(staging, out)
    except Exception as exc:
        shutil.rmtree(staging, ignore_errors=True)
        return _error(f"cannot write report: {type(exc).__name__}: {exc}")

    print(_dump(summary, None))
    return 1 if mismatches else 0


def _replay(path: Path) -> int:
    try:
        result = runner.replay(path)
    except Exception as exc:
        return _error(f"replay failed: {type(exc).__name__}: {exc}")
    print(_dump(result))
    return 0 if result["ok"] else 1


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="python -m tlp",
                                     description="SQLite ternary logic partitioning tester")
    commands = parser.add_subparsers(dest="command", required=True)
    campaign = commands.add_parser("campaign", help="generate and run test cases")
    campaign.add_argument("--seed", type=int, required=True)
    campaign.add_argument("--count", type=int, default=112)
    campaign.add_argument("--out", type=Path, required=True)
    replay = commands.add_parser("replay", help="rerun a saved mismatch artifact")
    replay.add_argument("artifact", type=Path)
    return parser


def main(argv: list[str] | None = None) -> int:
    try:
        args = _parser().parse_args(argv)
    except SystemExit as exc:  # argparse reports usage errors with code 2
        return exc.code if isinstance(exc.code, int) else 2
    if args.command == "campaign":
        return _campaign(args.seed, args.count, args.out)
    return _replay(args.artifact)


if __name__ == "__main__":
    raise SystemExit(main())
